import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Client } from '@stomp/stompjs';
import SockJS from 'sockjs-client';
import {
  ArrowLeft, Plane, Truck, Sparkles, Send, Gauge, SatelliteDish,
  BatteryFull, BatteryMedium, BatteryLow, BatteryWarning, Route,
  Search, ChevronLeft, ChevronRight, Camera, X, Layers, Compass, Navigation
} from 'lucide-react';
import ThemeToggle from './ThemeToggle';
import { useTheme } from '../context/ThemeContext';
import FleetMap from './FleetMap';

const VEHICLE_COLORS = ['#FF3366', '#00E5FF', '#00E676', '#FF9100', '#D500F9', '#FFEA00', '#2979FF'];

export const getVehicleColor = (vId) => {
  let hash = 0;
  for (let i = 0; i < (vId || '').length; i++) {
    hash = vId.charCodeAt(i) + ((hash << 5) - hash);
  }
  return VEHICLE_COLORS[Math.abs(hash) % VEHICLE_COLORS.length];
};

function BatteryIcon({ level }) {
  if (level === undefined || level === null) return <Gauge size={13} strokeWidth={2} />;
  if (level < 15) return <BatteryWarning size={13} strokeWidth={2} />;
  if (level < 40) return <BatteryLow size={13} strokeWidth={2} />;
  if (level < 80) return <BatteryMedium size={13} strokeWidth={2} />;
  return <BatteryFull size={13} strokeWidth={2} />;
}

export default function ManageFleetPage() {
  const navigate = useNavigate();
  const { theme } = useTheme();
  const [vehicles, setVehicles] = useState([]);
  const [telemetryData, setTelemetryData] = useState({});
  const [command, setCommand] = useState("");
  const [selectedVehicle, setSelectedVehicle] = useState(null);
  const [activeTraces, setActiveTraces] = useState({});

  // NEW UI STATES
  const [searchQuery, setSearchQuery] = useState('');
  const [isSidebarMinimized, setIsSidebarMinimized] = useState(false);
  const [isHudExpanded, setIsHudExpanded] = useState(true);
  const [pitch, setPitch] = useState(60);
  const [bearing, setBearing] = useState(-20);

  useEffect(() => {
    const socket = new SockJS('http://localhost:8080/ws-telemetry');
    const stompClient = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        fetch('http://localhost:8080/api/fleet/vehicles')
          .then(res => res.json())
          .then(data => {
            setVehicles(data);
            data.forEach(v => {
              stompClient.subscribe(`/topic/telemetry.${v.id}.position`, message => {
                const payload = JSON.parse(message.body);
                setTelemetryData(prev => ({ ...prev, [payload.vehicle_id]: payload }));
              });
            });
          })
          .catch(err => console.error("Error fetching vehicles:", err));
      },
    });

    stompClient.activate();
    return () => stompClient.deactivate();
  }, []);

  const handleCommandSubmit = (e) => {
    e.preventDefault();
    if (!command.trim()) return;
    console.log("Command submitted: ", command);
    setCommand("");
  };

  const vehicleById = useMemo(() => {
    const map = {};
    vehicles.forEach(v => { map[v.id] = v; });
    return map;
  }, [vehicles]);

  const filteredVehicles = vehicles.filter(v =>
    v.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    v.id.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const activeCount = Object.keys(telemetryData).length;
  const isDark = theme === 'dark';
  const hudBg = isDark ? 'var(--bg-glass, rgba(18, 18, 22, 0.95))' : 'rgba(255, 255, 255, 0.95)';
  const textColor = isDark ? '#fff' : '#111';
  const subtextColor = isDark ? '#888' : '#555';
  const borderColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.1)';
  const btnBg = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.04)';

  const controlColors = {
    flat2D: '#00b4d8',
    view3D: '#7209b7',
    north: '#f72585',
    east: '#4cc9f0',
    south: '#4895ef',
    west: '#3a0ca3'
  };

  const getColoredBtnStyle = (isActive, activeColor) => ({
    flex: 1,
    background: isActive ? activeColor : btnBg,
    border: `1px solid ${isActive ? activeColor : borderColor}`,
    borderRadius: '6px',
    color: isActive ? '#fff' : subtextColor,
    fontSize: '11px',
    padding: '6px 0',
    cursor: 'pointer',
    textTransform: 'uppercase',
    fontWeight: '700',
    transition: 'all 0.2s ease',
    boxShadow: isActive ? `0 4px 12px ${activeColor}50` : 'none'
  });

  const isAngleActive = (current, target) => Math.abs(current - target) < 2;

  return (
    <div className="fleet-shell page-enter" style={{ display: 'flex', width: '100vw', height: '100vh', overflow: 'hidden' }}>

      {/* SIDEBAR WITH MINIMIZATION & SEARCH */}
      <div className="sidebar" style={{ width: isSidebarMinimized ? '70px' : '380px', transition: 'width 0.3s ease', display: 'flex', flexDirection: 'column', position: 'relative', borderRight: `1px solid ${borderColor}` }}>

        {/* Minimize / Expand Toggle Button */}
        <button
          onClick={() => setIsSidebarMinimized(!isSidebarMinimized)}
          title={isSidebarMinimized ? "Expand Sidebar" : "Minimize Sidebar"}
          style={{
            position: 'absolute', top: '24px', right: '-14px', width: '28px', height: '28px',
            borderRadius: '50%', background: isDark ? '#2a2a35' : '#fff', border: `1px solid ${borderColor}`,
            display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', zIndex: 20,
            color: textColor, boxShadow: '0 2px 8px rgba(0,0,0,0.15)'
          }}
        >
          {isSidebarMinimized ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
        </button>

        {!isSidebarMinimized && (
          <>
            <button type="button" className="link-back" onClick={() => navigate('/')} style={{ margin: '16px 20px 0 20px' }}>
              <ArrowLeft size={14} strokeWidth={2} />
              Back to Portal
            </button>

            <div className="sidebar-header" style={{ padding: '16px 20px' }}>
              <div>
                <h2 className="sidebar-title">Fleet Orchestrator</h2>
                <p className="sidebar-subtitle">Live Telemetry &amp; Control</p>
              </div>
              <ThemeToggle />
            </div>

            {/* SEARCH BAR */}
            <div style={{ padding: '0 20px 14px 20px' }}>
              <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
                <Search size={14} color={subtextColor} style={{ position: 'absolute', left: '12px' }} />
                <input
                  type="text"
                  placeholder="Search fleet vehicles..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  style={{
                    width: '100%',
                    background: isDark ? '#22222c' : '#ffffff',
                    color: textColor,
                    border: `1px solid ${borderColor}`,
                    borderRadius: '8px',
                    padding: '8px 10px 8px 34px',
                    fontSize: '13px',
                    outline: 'none'
                  }}
                />
              </div>
            </div>

            {vehicles.length > 0 && (
              <div className="fleet-summary" style={{ padding: '0 20px 12px 20px' }}>
                <span><b>{vehicles.length}</b> registered</span>
                <span className="fleet-summary-dot">·</span>
                <span className="fleet-summary-active"><b>{activeCount}</b> active</span>
              </div>
            )}

            <div className="vehicle-list" style={{ flex: 1, overflowY: 'auto', padding: '0 20px 20px 20px' }}>
              {filteredVehicles.length === 0 ? (
                <div className="empty-state">
                  <SatelliteDish size={28} strokeWidth={1.5} />
                  <p>No matching vehicles found...</p>
                </div>
              ) : (
                filteredVehicles.map(v => {
                  const live = telemetryData[v.id] || {};
                  const isOnline = !!live.latitude;
                  const isGround = v.category === 'GROUND';
                  const isSelected = selectedVehicle === v.id;
                  const vColor = getVehicleColor(v.id);

                  return (
                    <div key={v.id} className={`vehicle-card ${isSelected ? 'selected' : ''}`} onClick={() => setSelectedVehicle(v.id)}>
                      <div className="vehicle-card-top">
                        <div className="vehicle-card-name">
                          <div className="vehicle-icon-badge" style={{ background: vColor, color: '#000', boxShadow: `0 0 10px ${vColor}40` }}>
                            {isGround ? <Truck size={15} strokeWidth={1.75} /> : <Plane size={15} strokeWidth={1.75} />}
                          </div>
                          <div>
                            <h4>{v.name}</h4>
                            <span className="vehicle-category">{v.category || 'UAV'}</span>
                          </div>
                        </div>
                        <div className={`status-pill ${isOnline ? 'is-active' : 'is-offline'}`}>
                          <span className="status-dot" />
                          {isOnline ? 'Active' : 'Offline'}
                        </div>
                      </div>

                      <div className="telemetry-grid">
                        <div>
                          <p className="telemetry-label">Latitude</p>
                          <p className="telemetry-value">{live.latitude ? live.latitude.toFixed(5) : '—'}</p>
                        </div>
                        <div>
                          <p className="telemetry-label">Longitude</p>
                          <p className="telemetry-value">{live.longitude ? live.longitude.toFixed(5) : '—'}</p>
                        </div>

                        {Object.keys(live)
                          .filter(key => !['vehicle_id', 'latitude', 'longitude', 'altitude', 'battery_level'].includes(key))
                          .map(customKey => (
                            <div key={customKey}>
                              <p className="telemetry-label">{customKey.replace(/_/g, ' ')}</p>
                              <p className="telemetry-value">{live[customKey]}</p>
                            </div>
                          ))
                        }
                      </div>

                      {live.altitude !== undefined && (
                        <div className="vehicle-card-footer">
                          <span><Gauge size={12} strokeWidth={2} /> {live.altitude.toFixed(1)}m</span>
                          {live.battery_level !== undefined && (
                            <span className={live.battery_level < 20 ? 'is-critical' : ''}>
                              <BatteryIcon level={live.battery_level} /> {live.battery_level}%
                            </span>
                          )}
                        </div>
                      )}

                      <div
                        style={{
                          marginTop: '12px', paddingTop: '12px', borderTop: `1px solid ${borderColor}`,
                          display: 'flex', alignItems: 'center', justifyContent: 'space-between'
                        }}
                        onClick={(e) => e.stopPropagation()}
                      >
                        <label style={{ fontSize: '12px', display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', color: 'var(--text-primary)', fontWeight: '500' }}>
                          <input
                            type="checkbox"
                            checked={!!activeTraces[v.id]}
                            onChange={() => setActiveTraces(prev => ({ ...prev, [v.id]: !prev[v.id] }))}
                            style={{ accentColor: vColor, cursor: 'pointer' }}
                          />
                          <Route size={14} color={vColor} />
                          Show 3D Trace
                        </label>

                        <button
                          onClick={() => navigate(`/vehicle/${v.id}`)}
                          style={{
                            background: 'transparent', border: `1px solid ${vColor}50`, color: vColor,
                            padding: '4px 10px', borderRadius: '6px', fontSize: '11px', fontWeight: '600',
                            cursor: 'pointer', textTransform: 'uppercase'
                          }}
                        >
                          Full History
                        </button>
                      </div>

                    </div>
                  );
                })
              )}
            </div>
          </>
        )}
      </div>

      {/* MAP PANEL WITH CAMERA HUD */}
      <div className="map-panel" style={{ flex: 1, position: 'relative', display: 'flex', flexDirection: 'column' }}>
        <FleetMap
          telemetryData={telemetryData}
          vehicleById={vehicleById}
          theme={theme}
          selectedVehicle={selectedVehicle}
          setSelectedVehicle={setSelectedVehicle}
          activeTraces={activeTraces}
        />

        {/* HUD CAMERA CONTROLS OVERLAY */}
        {isHudExpanded ? (
          <div style={{
            position: 'absolute', top: '20px', right: '20px', background: hudBg, backdropFilter: 'blur(15px)',
            border: `1px solid ${borderColor}`, borderRadius: '16px', padding: '20px', color: textColor,
            boxShadow: '0 20px 40px rgba(0,0,0,0.15)', zIndex: 10, display: 'flex', flexDirection: 'column', gap: '20px', width: '270px'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span style={{ fontSize: '13px', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Camera Settings</span>
              <X size={18} color={subtextColor} style={{ cursor: 'pointer' }} onClick={() => setIsHudExpanded(false)} />
            </div>

            {/* PITCH ANGLE */}
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '10px' }}>
                <div style={{ width: '38px', height: '38px', borderRadius: '10px', background: btnBg, border: `1px solid ${borderColor}`, display: 'flex', justifyContent: 'center', alignItems: 'center', perspective: '100px' }}>
                  <Layers size={20} color={controlColors.view3D} style={{ transform: `rotateX(${pitch}deg)`, transformStyle: 'preserve-3d', transition: 'transform 0.2s ease' }}/>
                </div>
                <div>
                  <div style={{ fontSize: '10px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Pitch Angle</div>
                  <div style={{ fontSize: '15px', fontWeight: '600' }}>{Math.round(pitch)}°</div>
                </div>
              </div>
              <input type="range" min="0" max="85" value={pitch} onChange={e => setPitch(Number(e.target.value))} style={{ width: '100%', cursor: 'pointer', accentColor: controlColors.view3D, marginBottom: '8px' }} />
              <div style={{ display: 'flex', gap: '8px' }}>
                <button style={getColoredBtnStyle(isAngleActive(pitch, 0), controlColors.flat2D)} onClick={() => setPitch(0)}>2D Flat</button>
                <button style={getColoredBtnStyle(isAngleActive(pitch, 65), controlColors.view3D)} onClick={() => setPitch(65)}>3D View</button>
              </div>
            </div>

            <div style={{ height: '1px', background: borderColor }} />

            {/* COMPASS ROSE BEARING UI */}
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '10px' }}>
                <div style={{ width: '38px', height: '38px', borderRadius: '50%', background: btnBg, border: `1px solid ${borderColor}`, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                  <Compass size={20} color={controlColors.north} style={{ transform: `rotate(${bearing - 45}deg)`, transition: 'transform 0.3s ease' }}/>
                </div>
                <div>
                  <div style={{ fontSize: '10px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Bearing</div>
                  <div style={{ fontSize: '15px', fontWeight: '600' }}>{Math.round(bearing)}°</div>
                </div>
              </div>

              <input type="range" min="-180" max="180" value={bearing} onChange={e => setBearing(Number(e.target.value))} style={{ width: '100%', cursor: 'pointer', accentColor: controlColors.north, marginBottom: '12px' }} />

              {/* COMPASS GRID */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '6px', maxWidth: '180px', margin: '0 auto' }}>
                <div />
                <button style={getColoredBtnStyle(isAngleActive(bearing, 0), controlColors.north)} onClick={() => setBearing(0)}>N</button>
                <div />

                <button style={getColoredBtnStyle(isAngleActive(bearing, -90), controlColors.west)} onClick={() => setBearing(-90)}>W</button>
                <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}><Navigation size={14} color={subtextColor} style={{ transform: `rotate(${bearing - 45}deg)`, transition: 'transform 0.3s ease' }} /></div>
                <button style={getColoredBtnStyle(isAngleActive(bearing, 90), controlColors.east)} onClick={() => setBearing(90)}>E</button>

                <div />
                <button style={getColoredBtnStyle(isAngleActive(bearing, 180) || isAngleActive(bearing, -180), controlColors.south)} onClick={() => setBearing(180)}>S</button>
                <div />
              </div>
            </div>
          </div>
        ) : (
          <div onClick={() => setIsHudExpanded(true)} style={{ position: 'absolute', top: '20px', right: '20px', background: hudBg, border: `1px solid ${borderColor}`, borderRadius: '50%', width: '44px', height: '44px', display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', zIndex: 10, color: textColor, transition: 'all 0.2s ease' }}>
            <Camera size={20} />
          </div>
        )}

        <div className="command-bar-wrap">
          <form onSubmit={handleCommandSubmit} className="command-bar">
            <Sparkles size={16} strokeWidth={2} className="command-bar-icon" />
            <input
              type="text"
              value={command}
              onChange={(e) => setCommand(e.target.value)}
              placeholder="Ask the AI to orchestrate the fleet (e.g., 'Deploy Alpha to grid sector 4')"
            />
            <button type="submit" className="btn btn-primary btn-compact">
              Dispatch
              <Send size={14} strokeWidth={2} />
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
